-- ============================================================================
-- 20260907090000_saved_searches
-- Phase 11: saved-search persistence (13 §13.2.4).
--
-- Spec: housing-platform/13 §13.2.4 — POST/GET/DELETE /api/v1/search/saved.
--       housing-platform/04 §4.6 — search query patterns; partial uniques.
--
-- Hand-edited extensions (not auto-generated by `prisma migrate dev`):
--   1. saved_searches_user_active_name_uniq — partial UNIQUE on
--      (user_id, name) WHERE deleted_at IS NULL. Prevents two active
--      saved searches with the same name per user, while still allowing
--      a user to soft-delete one and re-create with the same name.
-- ============================================================================

-- ── Tables ───────────────────────────────────────────────────────────────
CREATE TABLE "saved_searches" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "user_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "query" JSONB NOT NULL,
    "tenant_id" UUID NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT now(),
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT now(),
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "saved_searches_pkey" PRIMARY KEY ("id")
);

-- ── Indexes ──────────────────────────────────────────────────────────────
-- Prisma-tracked:
CREATE INDEX "saved_searches_user_idx" ON "saved_searches"("user_id");

-- Hand-edited:
CREATE UNIQUE INDEX "saved_searches_user_active_name_uniq"
    ON "saved_searches"("user_id", "name")
    WHERE "deleted_at" IS NULL;

-- ── Foreign keys ─────────────────────────────────────────────────────────
ALTER TABLE "saved_searches"
    ADD CONSTRAINT "saved_searches_user_id_fkey"
    FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE
    ON UPDATE NO ACTION;
